// Gemini returns clean fields; this step turns amounts into real
// numbers and decides whether the read is complete enough to trust.
const out = $input.first().json.output || {};

// "1.234,56", "1,234.56", "€ 950" — all become 1234.56 / 950
const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  let s = String(v).replace(/[^\d.,-]/g, '');
  const lastComma = s.lastIndexOf(','), lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = Number(s);
  return Number.isNaN(n) ? null : n;
};

const d = {
  supplier: out.supplier || null,
  number:   out.invoice_number || null,
  date:     out.invoice_date || null,
  due:      out.due_date || null,
  net:      toNum(out.net_amount),
  vat:      toNum(out.vat_amount),
  total:    toNum(out.total_amount),
  currency: out.currency || null,
};

// the three fields a bookkeeper cannot live without
const missing = [];
if (!d.supplier) missing.push('supplier');
if (!d.number)   missing.push('invoice number');
if (d.total === null) missing.push('total');

return [{ json: { ...d, confident: missing.length === 0, missing } }];

// The invoice comes from the parser; the input items are the rows
// already in your sheet, read a moment ago.
const d = $('Tidy up what Gemini found').first().json;
const rows = $input.all().map(r => r.json).filter(r => r && (r.supplier || r.number));
// "4248 GBP" looks unfinished in a message to the owner
const fmtMoney = v => v === null || v === undefined || Number.isNaN(Number(v)) ? String(v)
  : Number(v).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];

const key = `${(d.supplier||'').toLowerCase()}|${(d.number||'').toLowerCase()}|${d.total}`;
const rowKey = r => `${String(r.supplier||'').toLowerCase()}|${String(r.number||'').toLowerCase()}|${r.total}`;
// checked against the sheet itself — static data only backs it up between reads
const already = rows.some(r => rowKey(r) === key) || store.seen.includes(key);
if (!already && d.confident) store.seen.push(key);

let action, note;
if (!d.confident) {
  action = 'needs a human';
  note   = `Could not read: ${d.missing.join(', ')}. Parked in the review folder, nothing was written.`;
} else if (already) {
  action = 'STOPPED — duplicate';
  note   = `This looks like an invoice you already have: ${d.supplier} ${d.number} for ${fmtMoney(d.total)} ${d.currency||''}. Not added again.`;
} else {
  action = 'added to the sheet';
  note   = `Row written: ${d.supplier} · ${d.number} · ${d.date} · ${fmtMoney(d.total)} ${d.currency||''}`;
}

return [{ json: { action, note, ok_to_write: d.confident && !already, invoice: { supplier: d.supplier, number: d.number, date: d.date, due: d.due, net: d.net, vat: d.vat, total: d.total, currency: d.currency, vat_number: d.vat_number }, invoices_on_file: store.seen.length } }];

// one clean row, nothing else — the sheet maps columns from these names
const i = $input.first().json.invoice;
const pdf = $('Archive a copy in Drive').first().json.webViewLink || '';
return [{ json: { supplier: i.supplier, number: i.number, date: i.date, due: i.due,
                  net: i.net, vat: i.vat, total: i.total, currency: i.currency, pdf } }];
